import{_ as e}from"./chunks/image10.CXG-iZ2X.js";import{_ as o}from"./chunks/image11.B6ai34I9.js";import{_ as r}from"./chunks/image14.X3KdA_b9.js";import{_ as i}from"./chunks/image18.CewVGPWQ.js";import{_ as a}from"./chunks/2.BRgDBKom.js";import{_ as n,o as s,c as l,am as c}from"./chunks/framework.CenUaW7a.js";const d="/projects/AiMechaM1/en/advanced-kit/assets/image7.DNHEuVl4.webp",h="/projects/AiMechaM1/en/advanced-kit/assets/image8.1mb4SZnZ.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image9.DYE0wjhq.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image12.Cd7dIeUH.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image13.ClQGHY1k.png",u="/projects/AiMechaM1/en/advanced-kit/assets/image15.CH8xTBul.png",f="/projects/AiMechaM1/en/advanced-kit/assets/image16.B8HV-hdM.png",y="/projects/AiMechaM1/en/advanced-kit/assets/image17.BjjQCEXR.png",b="/projects/AiMechaM1/en/advanced-kit/assets/image19.C1DCJzso.png",w="/projects/AiMechaM1/en/advanced-kit/assets/image20.BoClXl7_.png",_="/projects/AiMechaM1/en/advanced-kit/assets/image21.DedUYWlJ.png",D=JSON.parse('{"title":"3.2 Lesson 2: Programming Platform Practice","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.2 Lesson 2 Programming Platform Practice.md","filePath":"docs/3. Course materials/3.2 Lesson 2 Programming Platform Practice.md"}'),x={name:"docs/3. Course materials/3.2 Lesson 2 Programming Platform Practice.md"};function k(v,t,P,C,A,L){return s(),l("div",null,[...t[0]||(t[0]=[c('<h1 id="_3-2-lesson-2-programming-platform-practice" tabindex="-1">3.2 Lesson 2: Programming Platform Practice <a class="header-anchor" href="#_3-2-lesson-2-programming-platform-practice" aria-label="Permalink to &quot;3.2 Lesson 2: Programming Platform Practice&quot;">​</a></h1><h2 id="_3-2-1-lesson-introduction" tabindex="-1">3.2.1 Lesson Introduction <a class="header-anchor" href="#_3-2-1-lesson-introduction" aria-label="Permalink to &quot;3.2.1 Lesson Introduction&quot;">​</a></h2><p>Entering the core stage of software programming, this lesson utilizes the WonderLab graphical programming platform and an RGB flashing police light project to guide learning through sequential, loop, and branch programming structures, completing the transition from hardware cognition to software control. Following a structured progression of &quot;platform introduction → basic syntax → project practice&quot;, the lesson employs three progressive tasks to master core programming logic. Upon completion of this course, the ability to independently write simple control programs will be acquired, laying a solid programming foundation for the subsequent study of functions such as line following and obstacle avoidance.</p><h2 id="_3-2-2-learning-objectives" tabindex="-1">3.2.2 Learning Objectives <a class="header-anchor" href="#_3-2-2-learning-objectives" aria-label="Permalink to &quot;3.2.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the concepts and application scenarios of the three basic program structures. Master the fundamental principles of graphical programming and block-stacking logic. Learn the RGB additive color-mixing principle and the hardware operation of LED lights.</p><p><strong>2.</strong> Independently complete the installation of the WonderLab programming platform, device connection, and program uploading operations. Master the usage of core control commands, including wait, repeat, and conditional judgment.</p><p><strong>3.</strong> Establish a structured programming thinking framework. Cultivate the ability to decompose complex tasks into simple steps and develop preliminary engineering thinking for program debugging and troubleshooting.</p><p><strong>4.</strong> Relate programming logic to automated control scenarios in daily life. Understand the wide application value of embedded programming in smart hardware, and stimulate interest in exploring robotics and artificial intelligence technologies.</p><h2 id="_3-2-3-preparation" tabindex="-1">3.2.3 Preparation <a class="header-anchor" href="#_3-2-3-preparation" aria-label="Permalink to &quot;3.2.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li>AiMecha M1 Mecanum-Wheel Car Advanced Kit</li><li>Type-C data cable</li><li>Computer × 1</li></ul><p><strong>Software Preparation</strong>:</p><ul><li>WonderLab graphical programming software</li></ul><h2 id="_3-2-4-hands-on-project" tabindex="-1">3.2.4 Hands-On Project <a class="header-anchor" href="#_3-2-4-hands-on-project" aria-label="Permalink to &quot;3.2.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Project Analysis</strong></p><p>Centered on the flashing police RGB light, this project follows the &quot;input → process → output&quot; control logic. The perception layer collects key and clock signals. The decision-making layer utilizes sequential, loop, and branch structures to process signal logic and schedule timing. The execution layer drives the RGB LED module to display the corresponding colors and flashing effects. Once the program starts, the hardware is initialized first. Different program structures then implement light switching, loop execution, and key-triggered control. The three structures progressively build the lighting control system, visually demonstrating the design approach of embedded programs from simple to complex.</p><img loading="lazy" height="540" width="960" src="'+d+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><ul><li><strong>Complete Program Preview</strong>:</li></ul><img loading="lazy" height="621" width="419" src="'+h+'" class="common_img" style="width:300px;aspect-ratio:419 / 621;"><p><strong>2. Software Installation and Introduction</strong></p><p>Refer to <a href="./../4. Deep Learning.html">4. Deep Learning</a>.</p><p><strong>3. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Program initialization</td><td style="text-align:center;"><img loading="lazy" height="89" width="261" src="'+g+'" class="common_img" style="width:160px;aspect-ratio:261 / 89;"></td><td style="text-align:left;">Program entry block. All program commands must be attached below it to execute first when the program starts.</td></tr><tr><td style="text-align:center;">Timing control</td><td style="text-align:center;"><img loading="lazy" height="100" width="326" src="'+e+'" class="common_img" style="width:160px;aspect-ratio:326 / 100;"></td><td style="text-align:left;">Sets the pause duration of the program to control the light-switching interval and flashing frequency.</td></tr><tr><td style="text-align:center;">Loop control</td><td style="text-align:center;"><img loading="lazy" height="276" width="415" src="'+o+'" class="common_img" style="width:130px;aspect-ratio:415 / 276;"></td><td style="text-align:left;">Core loop structure block. Program blocks placed inside repeat indefinitely.</td></tr><tr><td style="text-align:center;">Loop control</td><td style="text-align:center;"><img loading="lazy" height="294" width="421" src="'+p+'" class="common_img" style="width:130px;aspect-ratio:421 / 294;"></td><td style="text-align:left;">Loop structure for a specified number of times. Automatically exits the loop after completing the set count.</td></tr><tr><td style="text-align:center;">Conditional branch</td><td style="text-align:center;"><img loading="lazy" height="424" width="597" src="'+m+'" class="common_img" style="width:130px;aspect-ratio:597 / 424;"></td><td style="text-align:left;">Single-branch conditional structure. Executes the internal code blocks when the condition is true.</td></tr><tr><td style="text-align:center;">Conditional branch</td><td style="text-align:center;"><img loading="lazy" height="627" width="589" src="'+r+'" class="common_img" style="width:130px;aspect-ratio:589 / 627;"></td><td style="text-align:left;">Dual-branch conditional structure. Executes different code blocks depending on whether the condition is true or false.</td></tr><tr><td style="text-align:center;">Lighting control</td><td style="text-align:center;"><img loading="lazy" height="96" width="408" src="'+u+'" class="common_img" style="width:160px;aspect-ratio:408 / 96;"></td><td style="text-align:left;">Sets all RGB LEDs to a specified preset color such as red, yellow, blue, or green.</td></tr><tr><td style="text-align:center;">Lighting control</td><td style="text-align:center;"><img loading="lazy" height="96" width="744" src="'+f+'" class="common_img" style="width:300px;aspect-ratio:744 / 96;"></td><td style="text-align:left;">Customizes the light color using RGB primary color values ranging from 0 to 255.</td></tr><tr><td style="text-align:center;">Lighting control</td><td style="text-align:center;"><img loading="lazy" height="97" width="320" src="'+y+'" class="common_img" style="width:140px;aspect-ratio:320 / 97;"></td><td style="text-align:left;">Turns off all RGB LEDs and disables the lighting output.</td></tr><tr><td style="text-align:center;">Key detection</td><td style="text-align:center;"><img loading="lazy" height="72" width="397" src="'+i+'" class="common_img" style="width:160px;aspect-ratio:397 / 72;"></td><td style="text-align:left;">Conditional judgment block. Detects whether A key on the controller board is pressed and returns a boolean value.</td></tr></tbody></table><p><strong>4. Complete Program Description</strong></p><p><strong>Task 1: The RGB LED to Emit Red Light First and Switch to Blue Light via Sequential Structure</strong></p><ul><li>Drag the <code>Main program </code>block into the workspace as the program entry.</li><li>Add the block to <code>Set RGB light color</code> and select red so that the red light turns on first when the program starts.</li><li>Add the block to <code>wait 0.5 seconds</code> to control the duration of the red light.</li><li>Add the block to <code>Set RGB light color</code> and select blue to switch to the blue light after 0.5 s.</li><li>Program features: The commands execute sequentially from top to bottom. Each command executes only once, and the program terminates upon completion.</li></ul><img loading="lazy" height="350" width="417" src="'+b+'" class="common_img" style="width:300px;aspect-ratio:417 / 350;"><p><strong>Task 2: Loop Structure for Alternating Red and Blue Flashing</strong></p><ul><li>Drag the <code>Main program</code> block into the workspace as the program entry.</li><li>Add the <code>forever</code> loop block to build an infinite loop framework.</li><li>Inside the loop, sequentially add the commands to <code>Set RGB light color red</code> → <code>wait 0.5 seconds</code> → <code>Set RGB light color blue</code> → <code>wait 0.5 seconds</code>.</li><li>Program features: The four commands inside the loop execute repeatedly in alternation, creating a continuous red-and-blue flashing police light effect.</li><li>Key parameters: The wait duration determines the flashing frequency. A 0.5 s interval corresponds to 120 flashes per minute, which is consistent with the visual alertness design principles of police lights.</li></ul><img loading="lazy" height="356" width="297" src="'+w+'" class="common_img" style="width:300px;aspect-ratio:297 / 356;"><p><strong>Task 3: Branch Structure for Key-Triggered Lighting Effects</strong></p><ul><li>Drag the <code>Main program</code> block into the workspace and nest a <code>forever</code> block on the outside to ensure continuous detection of the key status.</li><li>Add the <code>if A key is pressed then</code> dual-branch conditional block.</li><li>True condition branch when the A key is pressed: Nest an inner <code>forever</code> loop. Inside the loop, sequentially turn on the red light → wait 0.5 seconds → turn on the blue light → wait 0.5 seconds → turn on the yellow light → wait 0.5 seconds to achieve a three-color cyclic flashing effect.</li><li>False condition branch when the A key is not pressed: Execute the block to <code>Turn off RGB lights</code> so that the lights remain off.</li><li>Project analysis: The program continuously polls and detects the key status. Pressing the A key triggers the flashing police light effect, and releasing the key turns off the lights, achieving interactive control.</li></ul><img loading="lazy" height="604" width="404" src="'+_+'" class="common_img" style="width:300px;aspect-ratio:404 / 604;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1vQnjkHE58XJU_cquYayobwkfJD5ZQ1KT?usp=sharing" target="_blank" rel="noreferrer">Program Files/Programming Platform Practice</a>.</strong></p></div><ul><li><p><strong>Program Upload</strong>:</p></li><li><p>Step 1: Power on the mecha controller and plug the Type-C data cable into the data port located above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button on the top toolbar of the software and select the COM port corresponding to CH340 from the dropdown list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to compile and download the program to the mecha controller.</p></li></ul><img loading="lazy" height="508" width="960" src="'+a+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-2-5-expansion-and-advancement" tabindex="-1">3.2.5 Expansion and Advancement <a class="header-anchor" href="#_3-2-5-expansion-and-advancement" aria-label="Permalink to &quot;3.2.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Project 1: Multi-Color Ambient Light Loop Effect</strong></p><p>Building upon the basic red and blue flashing, add green, yellow, purple, cyan, and other colors to design a multi-color ambient light loop program with a 5 s cycle. Set a distinct duration for each color by adjusting the wait time parameters to create a rhythmic visual breathing transition. Experiment further with the custom RGB value command to mix more personalized colors.</p><p><strong>Project 2: Key-Controlled Multi-Mode Light Switching</strong></p><p>Design a multi-state switching program that cycles through different lighting modes by pressing key A. The first press enters the red-and-blue police light mode, the second press enters the seven-color dazzling mode, the third press enters the breathing light mode, and the fourth press turns off all lights. Introduce a variable to record the current mode state and combine it with branch structures to implement the multi-mode switching logic, enhancing program interactivity and functional richness.</p><h2 id="_3-2-6-q-a" tabindex="-1">3.2.6 Q&amp;A <a class="header-anchor" href="#_3-2-6-q-a" aria-label="Permalink to &quot;3.2.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: What are the three basic structures of a program?</strong></p><p><strong>Answer</strong>: The three basic structures of a program are the sequential structure, the loop structure, and the branch structure.</p><p><strong>Q2: Why do RGB LEDs only need red, green, and blue to mix almost all colors?</strong></p><p><strong>Answer</strong>: RGB LEDs operate based on the principle of primary color light superposition, which is an additive color mixing model. The human retina contains three types of cone cells that are most sensitive to red, green, and blue light, respectively. The brain perceives different colors through integrating these three signals.</p><h2 id="_3-2-7-technical-support-and-discussion" tabindex="-1">3.2.7 Technical Support and Discussion <a class="header-anchor" href="#_3-2-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.2.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',48)])])}const E=n(x,[["render",k]]);export{D as __pageData,E as default};
